  private readonly collision: CameraRaycaster | undefined;

  get mode(): CameraMode { return this.modeValue; }
  get isTransitioning(): boolean { return this.transition !== undefined; }

  snapshot(): CameraSnapshot {
    return {
      mode: this.modeValue,
      position: copy(this.appliedPosition),
      target: copy(this.appliedTarget),
      yaw: this.yaw,
      pitch: this.pitch,
      distance: this.modeDistances[this.modeValue],
      transitioning: this.isTransitioning,
    };
  }

  setTarget(target: CameraTargetSource): void { this.targetSource = target; }
  setOverviewTarget(target: CameraTargetSource): void { this.overviewTargetSource = target; }

  setMode(mode: CameraMode, options: CameraTransitionOptions = {}): void {
    if (mode === this.modeValue) return;
    const duration = Math.max(0, options.duration ?? this.transitionSeconds);
    if (mode === 'free') {
      this.freePosition = copy(this.appliedPosition);
      this.freeTarget = copy(this.appliedTarget);
      this.syncOrbitFromPose(this.freePosition, this.freeTarget);
    }
    this.modeValue = mode;
    this.transition = duration > 0 ? {
      from: { position: copy(this.appliedPosition), target: copy(this.appliedTarget) },
      elapsed: 0,
      duration,
    } : undefined;
    if (duration === 0) this.applyPose(this.poseForMode());
  }

  resetToTarget(): void {
    this.modeDistances.aim = this.profiles.aim.distance;
    this.setMode('aim', { duration: 0 });
  }

  updateFromInput(deltaSeconds: number, input: InputSnapshot): void {
    if (input.wasPressed('camera-reset')) this.resetToTarget();
    const orbitActive = input.pointer.primaryDown || this.modeValue === 'free';
    this.update(deltaSeconds, {
      orbitX: orbitActive ? input.pointer.deltaX : 0,
      orbitY: orbitActive ? input.pointer.deltaY : 0,
      zoom: input.pointer.wheel,
      moveForward: input.isDown('camera-forward'),
      moveBackward: input.isDown('camera-backward'),
      moveLeft: input.isDown('camera-left'),
      moveRight: input.isDown('camera-right'),
    });
  }

  update(deltaSeconds: number, controls: CameraControlState = {}): void {
    const dt = clamp(Number.isFinite(deltaSeconds) ? deltaSeconds : 0, 0, 0.25);
    this.yaw -= (controls.orbitX ?? 0) * this.orbitSensitivity;
    this.pitch = clamp(this.pitch - (controls.orbitY ?? 0) * this.orbitSensitivity, MIN_PITCH, MAX_PITCH);
    if (this.modeValue !== 'free') {
      const profile = this.profiles[this.modeValue];
      this.modeDistances[this.modeValue] = clamp(
        this.modeDistances[this.modeValue] + (controls.zoom ?? 0) * this.zoomSensitivity,
        profile.minDistance,
        profile.maxDistance,
      );
    } else {
      this.moveFree(dt, controls);
    }

    const desired = this.poseForMode();
    if (this.transition) {
      this.transition.elapsed += dt;
      const progress = clamp(this.transition.elapsed / this.transition.duration, 0, 1);
      const eased = progress * progress * (3 - 2 * progress);
      this.applyPose({
        position: lerp(this.transition.from.position, desired.position, eased),
        target: lerp(this.transition.from.target, desired.target, eased),
      });
      if (progress === 1) this.transition = undefined;
      return;
    }
    this.applyPose(desired);
  }

  private createProfiles(overrides: CameraControllerOptions['profiles']): Record<CameraMode, CameraModeProfile> {
    const result = {} as Record<CameraMode, CameraModeProfile>;
    for (const mode of Object.keys(DEFAULT_PROFILES) as CameraMode[]) {
      const profile = { ...DEFAULT_PROFILES[mode], ...overrides?.[mode] };
      result[mode] = {
        ...profile,
        minDistance: Math.max(0.1, profile.minDistance),
        maxDistance: Math.max(profile.minDistance, profile.maxDistance),
      };
    }
    return result;
  }

  private poseForMode(): CameraPose {
    if (this.modeValue === 'free') return { position: copy(this.freePosition), target: copy(this.freeTarget) };
    const profile = this.profiles[this.modeValue];
    const baseTarget = resolveTarget(this.modeValue === 'overview' ? this.overviewTargetSource : this.targetSource);
    const target = { ...baseTarget, y: baseTarget.y + profile.targetHeight };
    const distance = this.modeDistances[this.modeValue];
    const horizontal = Math.cos(this.pitch) * distance;
    const desired = {
      x: target.x + Math.sin(this.yaw) * horizontal,
      y: target.y + Math.sin(this.pitch) * distance,
      z: target.z + Math.cos(this.yaw) * horizontal,
    };
    return {
      target,
      position: this.collision ? resolveCameraPosition(target, desired, this.collision, { minDistance: profile.minDistance }) : desired,
    };
  }

  private moveFree(dt: number, controls: CameraControlState): void {
    const forward = this.viewDirection();
    const right = { x: Math.cos(this.yaw), y: 0, z: -Math.sin(this.yaw) };
    let x = 0;
    let z = 0;
    if (controls.moveForward) { x += forward.x; z += forward.z; }
    if (controls.moveBackward) { x -= forward.x; z -= forward.z; }
    if (controls.moveRight) { x += right.x; z += right.z; }
    if (controls.moveLeft) { x -= right.x; z -= right.z; }
    const length = Math.hypot(x, z);
    if (length > 0) {
      const amount = this.freeMoveSpeed * dt / Math.max(1, length);
      this.freePosition.x += x * amount;
      this.freePosition.z += z * amount;
    }
    const direction = this.viewDirection();
    this.freeTarget = {
      x: this.freePosition.x + direction.x * this.profiles.free.distance,
      y: this.freePosition.y + direction.y * this.profiles.free.distance,
      z: this.freePosition.z + direction.z * this.profiles.free.distance,
    };
  }

  private viewDirection(): Vec3 {
    const horizontal = Math.cos(this.pitch);
    return { x: Math.sin(this.yaw) * horizontal, y: Math.sin(this.pitch), z: Math.cos(this.yaw) * horizontal };
  }

  private syncOrbitFromPose(position: Vec3, target: Vec3): void {
    const x = target.x - position.x;
    const y = target.y - position.y;
    const z = target.z - position.z;
    const horizontal = Math.hypot(x, z);
    if (horizontal > 1e-6 || Math.abs(y) > 1e-6) {
      this.yaw = Math.atan2(x, z);
      this.pitch = clamp(Math.atan2(y, horizontal), -HALF_PI + 0.01, HALF_PI - 0.01);
    }
  }

  private applyPose(pose: CameraPose): void {
    this.appliedPosition = copy(pose.position);
    this.appliedTarget = copy(pose.target);
    this.camera.position.set(pose.position.x, pose.position.y, pose.position.z);
    this.camera.lookAt(pose.target.x, pose.target.y, pose.target.z);
  }
}
