import { describe, expect, it } from 'vitest';
import type { InputSnapshot } from '../input';
import type { Vec3 } from '../contracts/math';
import { CameraController, type CameraView } from './CameraController';

class FakeCamera implements CameraView {
  position = {
    x: 0,
    y: 2,
    z: 5,
    set: (x: number, y: number, z: number): void => { this.position.x = x; this.position.y = y; this.position.z = z; },
  };
  lookedAt: Vec3 = { x: 0, y: 0, z: 0 };
  lookAt(x: number, y: number, z: number): void { this.lookedAt = { x, y, z }; }
}

const distance = (a: Vec3, b: Vec3): number => Math.hypot(a.x - b.x, a.y - b.y, a.z - b.z);

describe('CameraController', () => {
  it('frames the active ball in aim mode and responds to orbit and zoom', () => {
    const ball = { x: 1, y: 0, z: -2 };
    const camera = new FakeCamera();
    const controller = new CameraController(camera, { target: () => ball, transitionSeconds: 0 });
    const initial = controller.snapshot();
    controller.update(0, { orbitX: 80, zoom: 120 });
    const next = controller.snapshot();
    expect(next.mode).toBe('aim');
    expect(next.target).toEqual({ x: 1, y: 0.35, z: -2 });
    expect(next.yaw).not.toBe(initial.yaw);
    expect(next.distance).toBeGreaterThan(initial.distance);
  });

  it('tracks a moving ball in follow mode', () => {
    const ball = { x: 0, y: 0, z: 0 };
    const camera = new FakeCamera();
    const controller = new CameraController(camera, { target: () => ball, transitionSeconds: 0 });
    controller.setMode('follow');
    ball.x = 7;
    ball.z = -3;
    controller.update(1 / 60);
    expect(controller.snapshot()).toMatchObject({ mode: 'follow', target: { x: 7, y: 0.45, z: -3 } });
  });

  it('uses the independent overview target and a high overview angle', () => {
    const camera = new FakeCamera();
    const controller = new CameraController(camera, {
      target: { x: 0, y: 0, z: 0 },
      overviewTarget: { x: 20, y: 1, z: -10 },
      transitionSeconds: 0,
    });
    controller.setMode('overview');
    const snapshot = controller.snapshot();
    expect(snapshot.target).toEqual({ x: 20, y: 1.4, z: -10 });
    expect(snapshot.position.y - snapshot.target.y).toBeGreaterThan(10);
  });

  it('moves a free camera with WASD-style control state without moving the ball target', () => {
    const camera = new FakeCamera();
    const controller = new CameraController(camera, { target: { x: 0, y: 0, z: 0 }, transitionSeconds: 0 });
    controller.setMode('free');
    const before = controller.snapshot();
    controller.update(1, { moveForward: true, moveRight: true, orbitX: 20 });
    const after = controller.snapshot();
    expect(after.mode).toBe('free');
    expect(after.position).not.toEqual(before.position);
    expect(after.target).not.toEqual(before.target);
  });

  it('interpolates mode changes and completes the transition', () => {
    const camera = new FakeCamera();
    const controller = new CameraController(camera, { target: { x: 0, y: 0, z: 0 }, transitionSeconds: 0 });
    controller.setMode('follow', { duration: 0.5 });
    const start = controller.snapshot().position;
    controller.update(0.25);
    const halfway = controller.snapshot();
    expect(halfway.transitioning).toBe(true);
    expect(halfway.position).not.toEqual(start);
    controller.update(0.25);
    expect(controller.isTransitioning).toBe(false);
    expect(controller.mode).toBe('follow');
  });

  it('uses the existing raycast contract to keep camera positions clear of obstacles', () => {
    const camera = new FakeCamera();
    const controller = new CameraController(camera, {
      target: { x: 0, y: 0, z: 0 },
      transitionSeconds: 0,
      collision: { cast: () => ({ distance: 2 }) },
    });
    const snapshot = controller.snapshot();
    expect(distance(snapshot.position, snapshot.target)).toBeCloseTo(1.82);
  });

  it('maps the shared InputManager snapshot to free movement and reset', () => {
    const camera = new FakeCamera();
    const controller = new CameraController(camera, { target: { x: 0, y: 0, z: 0 }, transitionSeconds: 0 });
    controller.setMode('free');
    const input: InputSnapshot = {
      pointer: { x: 0, y: 0, deltaX: 10, deltaY: 0, wheel: 0, primaryDown: true },
      isDown: action => action === 'camera-forward',
      wasPressed: () => false,
      wasReleased: () => false,
    };
    const before = controller.snapshot().position;
    controller.updateFromInput(1, input);
    expect(controller.snapshot().position).not.toEqual(before);
  });
});
